<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api, http } from '../api'
import type { Category, Manual, Page } from '../types'
import { useAuthStore } from '../stores/auth'
const auth=useAuthStore(),categories=ref<Category[]>([]),rows=ref<Manual[]>([]),total=ref(0),loading=ref(false),drawer=ref(false),categoryDrawer=ref(false),editing=ref<Manual|null>(null),file=ref<File|null>(null),actionManualId=ref<string|null>(null)
const query=reactive({keyword:'',categoryId:'',status:'',page:1,pageSize:20}),form=reactive({categoryId:'',title:'',summary:''}),catForm=reactive({id:'',name:'',sortOrder:0,status:'ENABLED',version:0})
async function load(){loading.value=true;try{categories.value=await api.get('/manual-categories');const p=await api.get<Page<Manual>>('/manuals',query);rows.value=p.items;total.value=p.total}catch(e){ElMessage.error((e as Error).message)}finally{loading.value=false}}
function edit(row?:Manual){editing.value=row||null;Object.assign(form,row?{categoryId:row.categoryId,title:row.title,summary:row.summary}:{categoryId:categories.value[0]?.id||'',title:'',summary:''});file.value=null;drawer.value=true}
function choose(e:Event){file.value=(e.target as HTMLInputElement).files?.[0]||null}
async function save(){try{if(editing.value){await api.patch(`/manuals/${editing.value.id}`,form,editing.value.version);if(file.value){const latest=await api.get<Manual>(`/manuals/${editing.value.id}`);const fd=new FormData();fd.append('file',file.value);await http.post(`/manuals/${editing.value.id}/versions`,fd,{headers:{'If-Match':String(latest.version)}})}}else{if(!file.value){ElMessage.warning('请选择手册文件');return}const fd=new FormData();fd.append('categoryId',form.categoryId);fd.append('title',form.title);fd.append('summary',form.summary);fd.append('file',file.value);await http.post('/manuals',fd)}ElMessage.success('手册已保存');drawer.value=false;load()}catch(e){ElMessage.error((e as Error).message)}}
async function status(row:Manual,target:string){const selected={id:row.id,title:row.title,version:row.version};try{await ElMessageBox.confirm(`确认将《${selected.title}》设为 ${target}？`,'状态确认');actionManualId.value=selected.id;const updated=await api.post<Manual>(`/manuals/${selected.id}/${target==='PUBLISHED'?'publish':'archive'}`,{},selected.version);if(updated.id!==selected.id)throw new Error('服务端返回的手册与所选手册不一致，请刷新后重试');ElMessage.success(`《${selected.title}》状态已更新`);await load()}catch(e){if(e instanceof Error)ElMessage.error(e.message)}finally{if(actionManualId.value===selected.id)actionManualId.value=null}}
async function download(row:Manual){try{const r=await http.get(`/manuals/${row.id}/file`,{responseType:'blob'});const url=URL.createObjectURL(r.data);const a=document.createElement('a');a.href=url;a.download=row.fileName;a.click();URL.revokeObjectURL(url)}catch(e){ElMessage.error((e as Error).message)}}
function editCategory(c?:Category){Object.assign(catForm,c?{id:c.id,name:c.name,sortOrder:c.sortOrder,status:c.status,version:c.version}:{id:'',name:'',sortOrder:0,status:'ENABLED',version:0});categoryDrawer.value=true}
async function saveCategory(){try{const b={name:catForm.name,sortOrder:catForm.sortOrder,status:catForm.status};if(catForm.id)await api.patch(`/manual-categories/${catForm.id}`,b,catForm.version);else await api.post('/manual-categories',b);ElMessage.success('分类已保存');editCategory();load()}catch(e){ElMessage.error((e as Error).message)}}
async function removeCategory(c:Category){try{await ElMessageBox.confirm('仅空分类可以删除，确定继续？','删除分类',{type:'warning'});await api.delete(`/manual-categories/${c.id}`,c.version);load()}catch(e){if(e instanceof Error)ElMessage.error(e.message)}}
onMounted(load)
</script>
<template><div><div class="page-heading"><div><h2>维修手册</h2><p>维护本地手册文件、分类与发布状态</p></div><div v-if="auth.isAdmin"><el-button @click="categoryDrawer=true">分类管理</el-button><el-button type="primary" @click="edit()">上传手册</el-button></div></div><div class="panel toolbar"><el-input v-model="query.keyword" clearable placeholder="标题或文件名"/><el-select v-model="query.categoryId" clearable placeholder="全部分类" style="width:170px"><el-option v-for="c in categories" :key="c.id" :label="c.name" :value="c.id"/></el-select><el-select v-model="query.status" clearable placeholder="全部状态" style="width:150px"><el-option v-for="s in ['DRAFT','PUBLISHED','ARCHIVED']" :key="s" :label="s" :value="s"/></el-select><el-button type="primary" @click="load">查询</el-button></div><div class="panel table-panel"><el-table v-loading="loading" :data="rows" row-key="id" stripe><el-table-column prop="title" label="标题" min-width="220"/><el-table-column prop="fileName" label="文件" min-width="200" show-overflow-tooltip/><el-table-column label="大小" width="100"><template #default="{row}">{{(row.fileSize/1024/1024).toFixed(2)}} MB</template></el-table-column><el-table-column prop="versionNo" label="文件版本" width="90"/><el-table-column prop="scanStatus" label="扫描" width="100"/><el-table-column label="状态" width="110"><template #default="{row}"><el-tag>{{row.status}}</el-tag></template></el-table-column><el-table-column label="操作" width="260" fixed="right"><template #default="{row}"><el-button link :disabled="actionManualId!==null" @click="download(row)">下载</el-button><template v-if="auth.isAdmin"><el-button link type="primary" :disabled="actionManualId!==null" @click="edit(row)">编辑/换文件</el-button><el-button v-if="row.status!=='PUBLISHED'" link type="success" :loading="actionManualId===row.id" :disabled="actionManualId!==null&&actionManualId!==row.id" @click="status(row,'PUBLISHED')">发布</el-button><el-button v-if="row.status!=='ARCHIVED'" link type="warning" :loading="actionManualId===row.id" :disabled="actionManualId!==null&&actionManualId!==row.id" @click="status(row,'ARCHIVED')">归档</el-button></template></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="query.page" layout="total,prev,pager,next" :total="total" @change="load"/></div></div><el-drawer v-model="drawer" :title="editing?'编辑手册':'上传手册'" size="min(560px,96vw)"><el-form label-position="top" style="padding:0 22px"><el-form-item label="分类"><el-select v-model="form.categoryId" style="width:100%"><el-option v-for="c in categories" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item label="标题"><el-input v-model="form.title"/></el-form-item><el-form-item label="摘要"><el-input v-model="form.summary" type="textarea" :rows="4"/></el-form-item><el-form-item :label="editing?'替换文件（可选）':'手册文件'"><input type="file" accept=".pdf,.docx,.txt,.md" @change="choose"/><small style="display:block;color:#8a98aa">支持 PDF、DOCX、TXT、MD，最大 20 MB</small></el-form-item><el-button type="primary" style="width:100%" @click="save">保存</el-button></el-form></el-drawer><el-drawer v-model="categoryDrawer" title="手册分类" size="min(520px,96vw)"><div style="padding:0 20px"><el-table :data="categories" row-key="id"><el-table-column prop="name" label="名称"/><el-table-column prop="sortOrder" label="排序" width="80"/><el-table-column prop="status" label="状态" width="100"/><el-table-column label="操作" width="120"><template #default="{row}"><el-button link @click="editCategory(row)">编辑</el-button><el-button link type="danger" @click="removeCategory(row)">删除</el-button></template></el-table-column></el-table><el-divider/><div style="display:flex;gap:8px;flex-wrap:wrap"><el-input v-model="catForm.name" placeholder="分类名称" style="width:180px"/><el-input-number v-model="catForm.sortOrder" :min="0" style="width:100px"/><el-select v-model="catForm.status" style="width:110px"><el-option label="启用" value="ENABLED"/><el-option label="禁用" value="DISABLED"/></el-select><el-button type="primary" @click="saveCategory">{{catForm.id?'更新':'新增'}}</el-button></div></div></el-drawer></div></template>
